<template>
  <div class="fence-page"><BaseMap ref="baseMapRef"/><div class="fence-panel"><div class="panel-card"><div class="panel-title">青贮数字围栏·种植上图</div><div class="stats"><div><b>{{ fences.length }}</b><span>备案围栏</span></div><div><b>{{ totalArea.toFixed(1) }}</b><span>围栏面积（亩）</span></div><div><b>{{ geoCount }}</b><span>关联地块</span></div></div></div><div class="panel-card list-card"><div class="panel-title">围栏列表</div><el-input v-model="keyword" clearable placeholder="搜索备案编号或主体" class="fence-search"/><div v-for="f in filteredFences" :key="f.id" class="fence-item" @click="locate(f)"><div><b>{{ f.filedNo }}</b><p>{{ f.subjectName }}</p><small>{{ cropName(f.crop) }} · {{ f.createdAt }}</small></div><el-button link type="primary">定位</el-button></div><el-empty v-if="!filteredFences.length" description="暂无数字围栏"/></div></div><el-drawer v-model="drawerVisible" :title="current?.filedNo || '围栏详情'" size="420px"><template v-if="current"><el-descriptions :column="1" border><el-descriptions-item label="备案编号">{{ current.filedNo }}</el-descriptions-item><el-descriptions-item label="备案主体">{{ current.subjectName }}</el-descriptions-item><el-descriptions-item label="种植品种">{{ cropName(current.crop) }}</el-descriptions-item><el-descriptions-item label="备案日期">{{ current.createdAt }}</el-descriptions-item><el-descriptions-item label="关联地块">{{ currentGeo.features?.length || 0 }} 块</el-descriptions-item><el-descriptions-item label="围栏面积">{{ currentArea.toFixed(1) }} 亩</el-descriptions-item></el-descriptions><div class="sub-title">围栏内地块</div><el-table :data="currentGeo.features || []" size="small" border><el-table-column prop="properties.plotName" label="地块名称" min-width="160"/><el-table-column prop="properties.plotId" label="地块编号" width="110"/><el-table-column prop="properties.areaMu" label="面积（亩）" width="90"/></el-table><div class="drawer-actions"><el-button type="primary" size="small" @click="locate(current)">重新定位</el-button></div></template></el-drawer></div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import BaseMap from '@/components/map/BaseMap.vue'
import { fetchFences, fetchFenceGeoJSON } from '@/api/sil'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const baseMapRef = ref(null); const fences = ref([]); const geoMap = ref({}); const current = ref(null); const drawerVisible = ref(false); const keyword = ref(''); const filteredFences = computed(() => fences.value.filter((f) => !keyword.value || `${f.filedNo}${f.subjectName}`.includes(keyword.value))); const geoCount = computed(() => Object.values(geoMap.value).reduce((s, g) => s + (g.features?.length || 0), 0)); const totalArea = computed(() => Object.values(geoMap.value).reduce((s, g) => s + (g.features || []).reduce((a, f) => a + Number(f.properties?.areaMu || 0), 0), 0)); const currentGeo = computed(() => current.value ? geoMap.value[current.value.id] || { features: [] } : { features: [] }); const currentArea = computed(() => (currentGeo.value.features || []).reduce((s, f) => s + Number(f.properties?.areaMu || 0), 0)); const cropName = (c) => ({ silage_corn: '青贮玉米', alfalfa: '苜蓿' }[c] || c)
const locate = (f) => { current.value = f; drawerVisible.value = true; const feature = geoMap.value[f.id]?.features?.[0]; if (feature) { const coords = feature.geometry.coordinates[0]; const [lng, lat] = coords[0]; baseMapRef.value?.flyTo([lat, lng], 12) } }
const load = async () => { fences.value = await fetchFences(userStore.role); const entries = await Promise.all(fences.value.map(async (f) => [f.id, await fetchFenceGeoJSON(f)])); geoMap.value = Object.fromEntries(entries); const features = entries.flatMap(([, geo]) => geo.features || []); baseMapRef.value?.addGeoJSON('silFences', { type: 'FeatureCollection', features }, { style: { color: '#26a69a', weight: 2, fillColor: '#26a69a', fillOpacity: 0.3 }, onEachFeature: (feature, layer) => layer.on('click', () => locate(fences.value.find((f) => f.id === feature.properties.fenceId))) }) }
onMounted(() => setTimeout(load, 300))
</script>
<style scoped lang="scss">.fence-page{position:relative;height:100%;min-height:620px;overflow:hidden}.fence-panel{position:absolute;z-index:500;top:16px;left:16px;width:350px;max-height:calc(100% - 32px);overflow:auto}.panel-card{margin-bottom:12px;padding:14px;background:rgba(255,255,255,.95);border:1px solid #dce6f0;border-radius:10px;box-shadow:0 4px 16px rgba(40,70,100,.15)}.panel-title{font-weight:700;color:#24476c;margin-bottom:12px}.stats{display:flex;justify-content:space-between;text-align:center}.stats b{display:block;color:#168c86;font-size:22px}.stats span{font-size:11px;color:#7b8794}.fence-search{margin-bottom:8px}.fence-item{display:flex;justify-content:space-between;gap:8px;padding:10px 2px;border-top:1px solid #edf1f5;cursor:pointer}.fence-item b{font-size:12px;color:#168c86}.fence-item p{margin:4px 0;font-size:13px;color:#354b63}.fence-item small{color:#8b98a8}.sub-title{margin:16px 0 8px;padding-left:8px;border-left:3px solid #168c86;font-weight:600}.drawer-actions{margin-top:14px}</style>